const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define La Palma, Spain geometry (Canary Islands)
  const laPalma = ee.Geometry.Polygon([
    [[-18.0, 28.9], [-18.0, 28.5], [-17.7, 28.5], [-17.7, 28.9], [-18.0, 28.9]]
  ]);

  // 2. Define time periods
  const period1Start = '2023-07-15';
  const period1End = '2023-07-17';
  const period2Start = '2023-07-17';
  const period2End = '2023-07-19';

  // 3. Load FIRMS MODIS/VIIRS fire data
  let col1 = ee.ImageCollection('FIRMS')
    .filterBounds(laPalma)
    .filterDate(period1Start, period1End);

  let col2 = ee.ImageCollection('FIRMS')
    .filterBounds(laPalma)
    .filterDate(period2Start, period2End);

  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  // Try MODIS Thermal Anomalies if FIRMS not available
  if (size1 === 0 && size2 === 0) {
    col1 = ee.ImageCollection('MODIS/061/MOD14A1')
      .filterBounds(laPalma)
      .filterDate(period1Start, period1End);

    col2 = ee.ImageCollection('MODIS/061/MOD14A1')
      .filterBounds(laPalma)
      .filterDate(period2Start, period2End);
  }

  const finalSize1 = col1.size().getInfo();
  const finalSize2 = col2.size().getInfo();

  console.log(`Period 1 (Jul 15-16): ${finalSize1} images`);
  console.log(`Period 2 (Jul 17-18): ${finalSize2} images`);

  if (finalSize1 === 0 || finalSize2 === 0) {
    console.log('No fire data available for one or both periods');
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Calculate fire metrics (use MaxFRP - Fire Radiative Power)
  const img1 = col1.select('MaxFRP').max();
  const img2 = col2.select('MaxFRP').max();

  // Count fire pixels and sum FRP
  const stats1 = img1.reduceRegion({
    reducer: ee.Reducer.sum().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: laPalma,
    scale: 1000,
    maxPixels: 1e9
  });

  const stats2 = img2.reduceRegion({
    reducer: ee.Reducer.sum().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: laPalma,
    scale: 1000,
    maxPixels: 1e9
  });

  const frp1 = stats1.get('MaxFRP_sum').getInfo();
  const count1 = stats1.get('MaxFRP_count').getInfo();
  const frp2 = stats2.get('MaxFRP_sum').getInfo();
  const count2 = stats2.get('MaxFRP_count').getInfo();

  console.log(`Jul 15-16: FRP=${frp1}, Fire pixels=${count1}`);
  console.log(`Jul 17-18: FRP=${frp2}, Fire pixels=${count2}`);

  // 5. Validation and answer
  if (frp1 === null || frp2 === null) {
    console.log('Calculation failed');
    console.log('<answer>C3</answer>');
    return;
  }

  // Check if fires decreased
  if (frp2 < frp1 || count2 < count1) {
    console.log('Fire presence decreased');
    console.log('<answer>A</answer>');
  } else {
    console.log('Fire presence did not decrease');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
